  const nodes=S.current().items.map((x,i)=>{const p=positions.get(x.id),a=anchors.get(x.id);if(!p)return '';const image=window.AtlasArtwork.imageForItem(x),member=memberships(x.id),t=member.find(t=>t.visible),land=a?.name||'Idea';return `<g class="weave-item" data-weave-item="${esc(x.id)}">${a?`<line class="weave-leader" x1="${a.x}" y1="${a.y}" x2="${p.x}" y2="${p.y}"/><circle class="weave-land-pin" cx="${a.x}" cy="${a.y}" r="5" fill="${color(t||S.activeThread())}" data-land-pin="${esc(a.id)}"><title>${esc(a.name)}</title></circle>`:''}<g class="constellate-card${x.type==='concept'?' concept':' pinned'}${active===x.id||first===x.id||shiftFirst===x.id?' selected':''}" data-constellate-node="${esc(x.id)}" data-land="${esc(a?.id||'')}" transform="translate(${p.x-NW()/2},${p.y-NH/2})" tabindex="0" role="button" aria-label="${esc(x.title)}. ${esc(land)}. ${a?'Drag or use arrow keys to offset this label; its land pin stays fixed.':'Idea: drag freely.'}"><rect width="${NW()}" height="${NH}" rx="5"/><path class="weave-film-star" d="M0,-8 L2.6,-2.6 L8,0 L2.6,2.6 L0,8 L-2.6,2.6 L-8,0 L-2.6,-2.6Z" transform="translate(3,14)"/>${image?`<image class="weave-card-art" href="${esc(image)}" x="3" y="3" width="${NW()-6}" height="27" preserveAspectRatio="xMidYMid meet"/>`:''}${wrap(x.title).map((line,n)=>`<text x="8" y="${(image?44:24)+n*14}">${esc(line)}</text>`).join('')}<text class="weave-land-caption" x="8" y="77">${esc(land.slice(0,24))}</text><circle class="weave-connect-handle" data-connect-handle="${esc(x.id)}" cx="${NW()-8}" cy="${NH/2}" r="7" role="button" tabindex="0" aria-label="Connect from ${esc(x.title)}"/>${knotRings(x.id,15,NH-14)}<title>${esc(x.title)} · ${esc(land)} · ${esc(member.map(t=>t.name).join(' / '))}</title></g></g>`;}).join('');
