 function showContext(){if(reading)setRead(false);const x=S.current().items.find(x=>x.id===active);if(!x)return;openDock();inline.hidden=true;const member=memberships(x.id),refs=references(x),r=reference(x),links=S.current().links.filter(l=>l.source===x.id||l.target===x.id);context.hidden=false;context.innerHTML=`<h3>${esc(x.title)}</h3>${x.maker?`<p>${esc(x.maker)}</p>`:''}<p class="weave-placement">${x.type==='concept'?'Freely placed idea':r?esc(r.name)+(r.status==='sourced'?'':' · catalog link'):'Land not indexed · kept off the map'}</p><div class="constellate-actions"><button id="constellate-start-link">Connect</button>${x.record?'<button id="constellate-view">View '+(x.film?'film':'filmmaker')+'</button>':''}<button id="constellate-remove">Remove card</button></div><h4>${member.length>1?'Knot · crossing threads':'Thread membership'}</h4><div class="weave-memberships">${S.current().threads.map(t=>`<label><input type="checkbox" data-member-thread="${esc(t.id)}" ${t.items.includes(x.id)?'checked':''}><i style="background:${color(t)}"></i>${esc(t.name)}</label>`).join('')}</div>${refs.length>1?`<label for="weave-pin-reference">Land marker</label><select id="weave-pin-reference">${refs.map(ref=>`<option value="${esc(ref.id)}"${ref.id===r?.id?' selected':''}>${esc(ref.name)}</option>`).join('')}</select>`:''}<label for="weave-card-note">Note in ${esc(S.activeThread().name)}</label><textarea id="weave-card-note" rows="3" maxlength="10000">${esc(S.activeThread().notes[x.id]||'')}</textarea>${links.length?'<h4>Connections</h4>'+links.map(l=>`<button class="weave-note-link" data-edit-connection="${esc(l.id)}">${esc(l.label)}</button>${l.note?`<p>${esc(l.note)}</p>`:''}`).join(''):''}`;
  $('#constellate-start-link').onclick=()=>startLink(x.id);$('#constellate-view')?.addEventListener('click',()=>{exit({restore:false});x.film?A.openProfileFilm(x.record,x.film):A.selectRecord(x.record);});$('#constellate-remove').onclick=()=>{transaction('Remove card',()=>S.remove(x.id));active=null;context.hidden=true;};context.querySelectorAll('[data-member-thread]').forEach(input=>input.onchange=()=>{transaction('Edit thread membership',()=>input.checked?S.addToThread(x.id,input.dataset.memberThread):S.removeFromThread(x.id,input.dataset.memberThread));showContext();});$('#weave-pin-reference')?.addEventListener('change',e=>{transaction('Choose land reference',()=>{S.current().pins[x.id]=e.target.value;return S.save();});A.focusLandOnMap(e.target.value);showContext();});$('#weave-card-note').onchange=e=>transaction('Edit thread note',()=>S.threadNote(S.current().activeThread,x.id,e.target.value),false);context.querySelectorAll('[data-edit-connection]').forEach(b=>b.onclick=()=>connectionForm(S.current().links.find(l=>l.id===b.dataset.editConnection)));}
 function openDock(){document.body.classList.remove('weave-browsing');if(panel.hidden){panel.hidden=false;trigger.setAttribute('aria-expanded','true');relayout();}}
 function connectionForm(link){openDock();$('#constellate-mode span').textContent=link.id?'Edit connection':'Name this connection';reading=false;$('#weave-editor').hidden=false;$('#weave-read-panel').hidden=true;$('#weave-share-panel').hidden=true;context.hidden=true;connecting=false;first=shiftFirst=dragLink=pointer=null;draft=copy(link);draftKey=link.id||link.source+'|'+link.target;inline.hidden=false;const title=id=>S.current().items.find(x=>x.id===id)?.title||'';inline.innerHTML=`<form id="constellate-link-form"><h3>Connect</h3><p>${esc(title(link.source))} → ${esc(title(link.target))}</p><div class="weave-quick-labels">${['answers','echoes','shares land','shares language','same collective','counterpoint'].map(label=>`<button type="button" data-quick-label="${label}">${label}</button>`).join('')}</div><label for="constellate-link-label">Connection label</label><input id="constellate-link-label" required maxlength="180" value="${esc(link.label||'')}" placeholder="Or write your own"><details><summary>Note &amp; source</summary><label for="constellate-link-kind">Type</label><select id="constellate-link-kind"><option value="interpretation">Interpretation</option><option value="question">Question</option><option value="sourced-note">Sourced note</option></select><label for="constellate-link-note">Note (optional)</label><textarea id="constellate-link-note" rows="2">${esc(link.note||'')}</textarea><label for="constellate-link-source">https source (optional)</label><input id="constellate-link-source" type="url" value="${esc(link.sourceURL||'')}"></details><div class="constellate-actions"><button>Save connection</button>${link.id?'<button type="button" id="constellate-remove-link">Remove</button>':''}<button type="button" id="constellate-cancel-link">Cancel</button></div></form>`;$('#constellate-link-kind').value=link.kind||'interpretation';$('#constellate-link-form').onsubmit=e=>{e.preventDefault();const value={...link,label:$('#constellate-link-label').value.trim(),kind:$('#constellate-link-kind').value,note:$('#constellate-link-note').value,sourceURL:$('#constellate-link-source').value.trim()};if(!value.label)return;if(value.sourceURL&&!/^https:\/\//i.test(value.sourceURL)){status('Use an https source.');return;}if(value.kind==='sourced-note'&&!value.sourceURL){status('Add an https source for a sourced note.');return;}if(transaction(link.id?'Edit connection':'Add connection',()=>S.link(value))){inline.hidden=true;draft=draftKey=null;active=link.target;showContext();status('Connection saved.');}};inline.querySelectorAll('[data-quick-label]').forEach(b=>b.onclick=()=>{$('#constellate-link-label').value=b.dataset.quickLabel;$('#constellate-link-form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));});$('#constellate-cancel-link').onclick=()=>{inline.hidden=true;draft=draftKey=null;};$('#constellate-remove-link')?.addEventListener('click',()=>{transaction('Remove connection',()=>S.removeLink(link.id));inline.hidden=true;draft=draftKey=null;});renderGraph();const head=$('#constellate-popup .constellate-heading');if(head&&head.nextElementSibling!==inline)head.after(inline);inline.scrollIntoView({block:'nearest'});$('#constellate-popup').scrollTop=0;$('#constellate-link-label').focus({preventScroll:true});}
 function renderResults(){const q=norm($('#constellate-search').value).trim(),found=catalog.filter(x=>(q||x.type==='film')&&norm([x.title,x.maker,x.community,...tags(x).flatMap(t=>[t.term,t.indigenousTerm,t.gloss,t.language])].filter(Boolean).join(' ')).includes(q)).sort((a,b)=>Number(!!b.image)-Number(!!a.image)||a.title.localeCompare(b.title)).slice(0,6),used=new Set();$('#constellate-results').innerHTML=found.map(x=>{const own=existingWork(x),has=own&&S.activeThread().items.includes(own.id),image=x.image&&!used.has(x.image)?x.image:'';if(image)used.add(image);return `<div class="constellate-result">${image?`<img src="${esc(image)}" alt="" loading="lazy">`:''}<span><strong>${esc(x.title)}</strong><small>${esc(x.type==='film'?x.maker:x.community)}</small>${tags(x).length?`<small class="weave-theme-tags">${esc(tags(x).slice(0,3).map(t=>t.term).join(' · '))}</small>`:''}</span><button data-constellate-add="${esc(x.id)}">${has?'Find card':'+ Add'}</button></div>`;}).join('')||'<p>No matches.</p>';}
 function renderLegend(){const c=S.current();$('#weave-legend').innerHTML=c.threads.map((t,i)=>`<div class="weave-legend-row${t.id===c.activeThread?' active':''}"><label title="Show ${esc(t.name)}"><input type="checkbox" data-thread-visible="${esc(t.id)}"${t.visible?' checked':''}><span class="sr-only">Show thread</span></label><button data-thread-active="${esc(t.id)}" aria-pressed="${t.id===c.activeThread}"><i style="background:${color(t)}"></i><span>${i+1}. ${esc(t.name)}</span><small>${t.items.length}</small></button></div>`).join('');$('#weave-legend').querySelectorAll('[data-thread-visible]').forEach(el=>el.onchange=()=>transaction('Toggle thread',()=>{c.threads.find(t=>t.id===el.dataset.threadVisible).visible=el.checked;return S.save();}));$('#weave-legend').querySelectorAll('[data-thread-active]').forEach(b=>b.onclick=()=>{busy=true;c.activeThread=b.dataset.threadActive;S.save();busy=false;known.set(c.id,copy(c));render();if(active&&!context.hidden)showContext();});}
 function renderOrder(){const t=S.activeThread();$('#weave-order-title').textContent=t.name;$('#weave-order-list').innerHTML=t.items.map((id,i)=>{const x=S.current().items.find(x=>x.id===id),a=x&&reference(x);return x?`<li draggable="true" data-thread-position="${i}"><button data-order-select="${esc(id)}"><b>${i+1}</b><span>${esc(x.title)}<small>${esc(x.type==='concept'?'Idea':a?.name||'Land not indexed')}</small></span></button><div class="weave-order-move"><button data-order-move="${i}" data-direction="-1" aria-label="Move ${esc(x.title)} earlier"${i===0?' disabled':''}>↑</button><button data-order-move="${i}" data-direction="1" aria-label="Move ${esc(x.title)} later"${i===t.items.length-1?' disabled':''}>↓</button></div></li>`:'';}).join('')||'<li class="weave-empty">Add the first card to this thread.</li>';$('#weave-order-list').querySelectorAll('[data-order-select]').forEach(b=>b.onclick=()=>{const x=S.current().items.find(x=>x.id===b.dataset.orderSelect),ref=reference(x);if(ref)A.focusLandOnMap(ref.id);choose(x.id);});$('#weave-order-list').querySelectorAll('[data-order-move]').forEach(b=>b.onclick=()=>transaction('Reorder thread',()=>S.reorderThread(t.id,+b.dataset.orderMove,+b.dataset.orderMove+Number(b.dataset.direction))));}
 function readSteps(){return S.current().threads.filter(t=>t.visible).flatMap(t=>t.items.map(id=>({thread:t,item:S.current().items.find(x=>x.id===id)})).filter(x=>x.item));}
 function renderRead(){const c=S.current(),steps=readSteps();readIndex=Math.max(0,Math.min(steps.length-1,readIndex));$('#weave-read-panel').innerHTML=`<h3>${esc(c.name)}</h3>${c.author?`<p>${esc(c.author)}</p>`:''}${c.note?`<p class="weave-prose">${esc(c.note)}</p>`:''}<nav class="weave-read-nav"><button id="weave-read-prev"${readIndex<=0?' disabled':''}>← Previous</button><span>${steps.length?readIndex+1:0} / ${steps.length}</span><button id="weave-read-next"${readIndex>=steps.length-1?' disabled':''}>Next →</button></nav>${c.threads.filter(t=>t.visible).map(t=>`<section class="weave-read-thread"><h4><i style="background:${color(t)}"></i>${esc(t.name)}</h4>${t.description?`<p class="weave-prose">${esc(t.description)}</p>`:''}<ol>${t.items.map((id,i)=>{const x=c.items.find(x=>x.id===id);if(!x)return '';const at=steps.findIndex(s=>s.thread.id===t.id&&s.item.id===id),links=c.links.filter(l=>l.source===id||l.target===id);return `<li${at===readIndex?' aria-current="step"':''}><button data-read-step="${at}">${esc(x.title)}</button>${x.maker?`<small>${esc(x.maker)}${x.year?' · '+esc(x.year):''}</small>`:''}${t.notes[id]?`<p class="weave-prose">${esc(t.notes[id])}</p>`:''}${links.map(l=>`<p class="weave-read-note"><b>${esc(l.label)}</b>${l.note?' · '+esc(l.note):''}${l.sourceURL?` <a href="${esc(l.sourceURL)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}</p>`).join('')}${x.href?`<a href="${esc(x.href)}" target="_blank" rel="noopener noreferrer">Film or filmmaker ↗</a>`:''}</li>`;}).join('')}</ol></section>`).join('')||'<p>Add cards to a visible thread to begin reading.</p>'}<button id="weave-read-print">Print reading path</button>`;const step=at=>{readIndex=at;const x=readSteps()[at]?.item;if(!x)return;active=x.id;const r=reference(x);if(r)A.focusLandOnMap(r.id);renderRead();renderGraph();};$('#weave-read-prev').onclick=()=>step(readIndex-1);$('#weave-read-next').onclick=()=>step(readIndex+1);$('#weave-read-panel').querySelectorAll('[data-read-step]').forEach(b=>b.onclick=()=>step(+b.dataset.readStep));$('#weave-read-print').onclick=()=>window.print();}
 function setRead(value){reading=value;openDock();$('#weave-editor').hidden=reading;$('#weave-read-panel').hidden=!reading;$('#weave-share-panel').hidden=true;$('#constellate-read').setAttribute('aria-pressed',String(reading));$('#constellate-read').textContent=reading?'Edit':'Read';if(reading)renderRead();updateAddress();}
 function render(){if(!enabled)return;const c=S.current(),options=S.state.collections.map(x=>`<option value="${esc(x.id)}"${x.id===c.id?' selected':''}>${esc(x.name)}</option>`).join('');if($('#constellate-collection').innerHTML!==options)$('#constellate-collection').innerHTML=options;$('#constellate-mode span').textContent=connecting?(first?'Choose another card':'Choose first card'):shiftFirst?'Shift-click another card':c.name;$('#constellate-connect').setAttribute('aria-pressed',String(connecting));$('#constellate-fit').disabled=!c.items.length;const x=selectedItem();$('#constellate-add-current').hidden=!x;$('#constellate-add-current').textContent=x?.type==='maker'?'Add selected filmmaker':'Add selected film';if(document.activeElement!==$('#weave-title'))$('#weave-title').value=c.name;if(document.activeElement!==$('#weave-author'))$('#weave-author').value=c.author||'';if(document.activeElement!==$('#weave-note'))$('#weave-note').value=c.note||'';renderLegend();renderResults();renderOrder();renderGraph();updateHistory();if(reading)renderRead();}
 function download(value,type,name){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const jsonExport=()=>({format:'Indigenous Cinema Atlas weave',version:2,active:S.current().id,collections:[copy(S.current())]});
 function shareURL(mode=$('#weave-share-mode')?.value||'read'){const payload=btoa(unescape(encodeURIComponent(JSON.stringify({version:2,weave:copy(S.current())})))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');if(payload.length>64000)return null;const u=new URL('./',location.href);u.searchParams.set('constellate','1');u.searchParams.set('weave',S.current().id);if(mode==='play')u.searchParams.set('play','1');else u.searchParams.set('read','1');u.hash='weave='+payload;return u.href;}
 async function packWeave(){const json=JSON.stringify({version:2,weave:copy(S.current())});if(!window.CompressionStream)return null;const buf=new Uint8Array(await new Response(new Blob([json]).stream().pipeThrough(new CompressionStream('deflate-raw'))).arrayBuffer());let bin='';for(let i=0;i<buf.length;i+=8192)bin+=String.fromCharCode(...buf.subarray(i,i+8192));return 'z'+btoa(bin).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
 async function shareURLAsync(mode=$('#weave-share-mode')?.value||'read'){const packed=await packWeave().catch(()=>null),plain=shareURL(mode);if(!packed)return plain;const u=new URL('./',location.href);u.searchParams.set('constellate','1');u.searchParams.set('weave',S.current().id);if(mode==='play')u.searchParams.set('play','1');else u.searchParams.set('read','1');u.hash='weave='+packed;return u.href;}
 function citation(url=$('#weave-url')?.value||shareURL()){const c=S.current();return `${c.author||'Anonymous curator'}. “${c.name}.” Indigenous Cinema Atlas: Abya Yala and Turtle Island, user-authored weave, ${String(c.updatedAt||'').slice(0,10)}. ${url||'JSON export'}`;}
 async function copyText(value,fallback){try{await navigator.clipboard.writeText(value);status('Copied.');}catch{if(fallback){fallback.value=value;fallback.focus();fallback.select();}status('Select and copy the text.');}}
 async function showShare(){openDock();$('#weave-share-panel').hidden=false;$('#weave-editor').hidden=true;$('#weave-read-panel').hidden=true;const url=await shareURLAsync();$('#weave-url').value=url||'';$('#weave-copy-url').disabled=!url;$('#weave-citation').textContent=citation(url);if(!url)status('This weave is too large for a reliable share URL. Export its JSON instead.');}
 function csvExport(){const c=S.current(),field=v=>{const x=String(v??'');return '"'+(/^[=+\-@\t\r]/.test(x)?"'"+x:x).replace(/"/g,'""')+'"';},rows=[['weave_id','weave','author','thread','order','type','title','filmmaker','year','land_reference','themes','note','connection_notes','sources']];for(const t of c.threads)for(const[id,i]of t.items.map((id,i)=>[id,i])){const x=c.items.find(x=>x.id===id);if(!x)continue;const links=c.links.filter(l=>l.source===id||l.target===id);rows.push([c.id,c.name,c.author,t.name,i+1,x.type,x.title,x.maker,x.year,reference(x)?.name||'',tags(x).map(t=>t.term).join('; '),t.notes[id]||'',links.map(l=>l.label+(l.note?': '+l.note:'')).join('; '),links.map(l=>l.sourceURL).filter(Boolean).join('; ')]);}return '\uFEFF'+rows.map(r=>r.map(field).join(',')).join('\r\n');}
